def resolve(path, cwd, links):
    # Validate cwd
    if not cwd or cwd[0] != '/':
        return None

    # Normalize cwd (remove trailing slashes, except for root)
    if cwd != '/' and cwd.endswith('/'):
        cwd = cwd.rstrip('/')

    # Start with cwd if path is relative
    if not path or path[0] != '/':
        current = cwd
        components = path.split('/') if path else []
    else:
        current = '/'
        components = path.split('/')[1:]  # Skip empty first element from leading '/'

    link_count = 0
    i = 0

    while i < len(components):
        comp = components[i]

        # Skip empty components and '.'
        if comp == '' or comp == '.':
            i += 1
            continue

        # Handle '..'
        if comp == '..':
            if current != '/':
                # Move to parent
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Append the component
        if current == '/':
            current = '/' + comp
        else:
            current = current + '/' + comp

        # Check if current path is a symlink
        if current in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[current]

            # Parse remaining components after this one
            remaining = components[i+1:]

            # Parse target components
            if target.startswith('/'):
                # Absolute symlink
                current = '/'
                target_components = target.split('/')[1:]  # Skip empty first element
            else:
                # Relative symlink - relative to the directory containing the link
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
                target_components = target.split('/')

            # Continue with target components followed by remaining components
            components = target_components + remaining
            i = 0
        else:
            i += 1

    # Return result without trailing slash (except for '/')
    if current == '/':
        return '/'
    else:
        return current

